import java.util.Scanner;

public class splitITup {
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        int n = scan.nextInt();
        String target = scan.next();

        int openCount = 0;
        int closeCount = 0;
        for (int i = 0; i < n; i++) {
            char c = target.charAt(i);
            if (c == '(') openCount++;
            if (c == ')') closeCount++;
        }

        int[] starts = new int[openCount];
        int[] ends = new int[closeCount];
        int si = 0;
        int ei = 0;
        for (int i = 0; i < n; i++) {
            char c = target.charAt(i);
            if (c == '(') starts[si++] = i;
            if (c == ')') ends[ei++] = i;
        }

        int count = 0;
        for (int i = 0; i < ends.length; i++) {
            String s = target.substring(starts[i] + 1, ends[i]);
            String[] parts = s.split("_");
            for (String part : parts) {
                if (!part.equals("")) count++;
            }
        }

        int Max = 0;
        int[] extendedEnds = new int[ends.length + 1];
        int[] extendedStarts = new int[starts.length + 1];
        extendedEnds[0] = 0;
        for (int i = 0; i < ends.length; i++) extendedEnds[i + 1] = ends[i];
        for (int i = 0; i < starts.length; i++) extendedStarts[i] = starts[i];
        extendedStarts[starts.length] = target.length();

        int i = target.charAt(0) == '(' ? 1 : 0;
        for (; i < extendedEnds.length; i++) {
            int from = target.charAt(extendedEnds[i]) == ')' ? extendedEnds[i] + 1 : extendedEnds[i];
            String s = target.substring(from, extendedStarts[i]);
            String[] parts = s.split("_");
            for (String part : parts) {
                if (part.length() > Max && !part.contains("(") && !part.contains(")")) {
                    Max = part.length();
                }
            }
        }

        System.out.println(Max + " " + count);
    }
}
